var runtimeAPI;

// Use fetch for Node 18+ or fallback to node-fetch
const fetch = globalThis.fetch || require('node-fetch');

async function callClaudeAPI(apiKey, model, messages, systemMessage, stream = false) {
    console.log('=== Calling Claude API directly ===');
    
    const requestBody = {
        model: model,
        max_tokens: 4000,
        messages: messages,
        system: systemMessage
    };

    if (stream) {
        requestBody.stream = true;
    }
    
    const response = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'x-api-key': apiKey,
            'anthropic-version': '2023-06-01'
        },
        body: JSON.stringify(requestBody)
    });

    if (!response.ok) {
        const errorText = await response.text();
        console.error('Claude API error:', response.status, errorText);
        throw new Error(`Claude API error: ${response.status} - ${errorText}`);
    }

    if (stream) {
        return response; // Return the response object for streaming
    } else {
        const data = await response.json();
        console.log('Claude API response received');
        return data;
    }
}

module.exports = {
    init: function(_runtimeAPI) {
        runtimeAPI = _runtimeAPI;
    },
    sendMessage: async function(req, res) {
        console.log('=== AI admin endpoint called (direct version) ===');
        
        try {
            const { apiKey, model, messages, system, stream } = req.body;
            
            if (!apiKey) {
                return res.status(400).json({ 
                    error: { 
                        message: 'API key is required', 
                        code: 'missing_api_key' 
                    } 
                });
            }

            console.log('Calling Claude API directly with model:', model, 'stream:', stream);

            if (stream) {
                // Set up streaming response
                res.writeHead(200, {
                    'Content-Type': 'text/plain; charset=utf-8',
                    'Cache-Control': 'no-cache',
                    'Connection': 'keep-alive'
                });

                const response = await callClaudeAPI(apiKey, model, messages, system, true);
                const reader = response.body.getReader();
                const decoder = new TextDecoder();

                try {
                    while (true) {
                        const { done, value } = await reader.read();
                        if (done) {
                            res.write('data: [DONE]\n\n');
                            break;
                        }

                        const chunk = decoder.decode(value, { stream: true });
                        const lines = chunk.split('\n');

                        for (const line of lines) {
                            if (line.trim()) {
                                res.write(`${line}\n`);
                            }
                        }
                    }
                } finally {
                    reader.releaseLock();
                    res.end();
                }
            } else {
                // Regular non-streaming response
                const result = await callClaudeAPI(apiKey, model, messages, system, false);
                res.json(result);
            }
        } catch (error) {
            console.error('AI endpoint error:', error);
            
            if (req.body.stream) {
                res.write(`data: {"type": "error", "message": "${error.message}"}\n\n`);
                res.end();
            } else {
                res.status(500).json({ 
                    error: { 
                        message: error.message, 
                        code: 'api_error' 
                    } 
                });
            }
        }
    }
}; 